#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import os
import sys
import time
import textwrap
import xml.dom.minidom as minidom

class ErrorReporter:
    def __init__(self, monochrome=False):
        self.monochrome = monochrome
        self.colors = {
            'red': '\033[91m',
            'green': '\033[92m', 
            'yellow': '\033[93m',
            'blue': '\033[94m',
            'magenta': '\033[95m',
            'cyan': '\033[96m',
            'reset': '\033[0m'
        }

    def colorize(self, text, color='cyan'):
        """Apply color to console text if not in monochrome mode."""
        if self.monochrome:
            return text
        return f"{self.colors.get(color, '')}{text}{self.colors['reset']}"

    def get_text(self, node):
        """Extract text from XML node."""
        return ''.join(
            child.nodeValue for child in node.childNodes 
            if child.nodeType == child.TEXT_NODE
        ).strip()

    def parse_aws_error(self, xml_error):
        """Parse AWS XML error message."""
        try:
            dom = minidom.parseString(xml_error)
            error_code = self.get_text(dom.getElementsByTagName('Code')[0])
            error_message = self.get_text(dom.getElementsByTagName('Message')[0])
            return error_code, error_message
        except Exception as e:
            return 'Unknown', str(e)

    def print_error(self, message, error_type='error'):
        """Print formatted error message."""
        color_map = {
            'error': 'red',
            'warning': 'yellow',
            'info': 'blue'
        }
        color = color_map.get(error_type.lower(), 'red')
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        formatted_msg = f"[{timestamp}] {error_type.upper()}: {message}"
        print(self.colorize(formatted_msg, color), file=sys.stderr)

    def aws_print_error(self, xml_error):
        """Print AWS-specific error with detailed information."""
        error_code, error_message = self.parse_aws_error(xml_error)
        self.print_error(f"AWS Error {error_code}: {error_message}", 'error')

    def print_help(self, script_name, description, options):
        """Generate and display help documentation."""
        help_text = f"{description}\n\nUsage: {script_name} [OPTIONS]\n\nOptions:"
        for opt, details in options.items():
            help_text += f"\n  {opt:<15} {details}"

        print(textwrap.dedent(help_text))

    def terminate_script(self, exit_code=1, message=None):
        """Terminate script with optional error message."""
        if message:
            self.print_error(message)
        sys.exit(exit_code)

def main():
    reporter = ErrorReporter(monochrome=False)

    try:
        # Example error handling scenario
        xml_error = '''
        <Error>
            <Code>AccessDenied</Code>
            <Message>Access denied to resource</Message>
        </Error>
        '''
        reporter.aws_print_error(xml_error)

        # Example help documentation
        options = {
            '-h, --help': 'Show this help message',
            '-v, --verbose': 'Enable verbose logging',
            '--monochrome': 'Disable color output'
        }
        reporter.print_help(
            os.path.basename(__file__), 
            "AWS Error Reporting Utility", 
            options
        )

    except Exception as e:
        reporter.terminate_script(message=str(e))

if __name__ == '__main__':
    main()

import math
import random
import numpy as np
import moderngl
import pygame
import glm

class TerrainLightRenderer:
    def __init__(self, width=800, height=600):
        pygame.init()
        self.width = width
        self.height = height
        self.screen = pygame.display.set_mode((width, height), pygame.OPENGL | pygame.DOUBLEBUF)
        pygame.display.set_caption("Dynamic Terrain Lighting Simulation")

        self.ctx = moderngl.create_context()
        self.ctx.enable(moderngl.DEPTH_TEST)

        self.generate_heightmap()
        self.setup_shader_programs()
        self.create_light_sources()
        self.setup_camera()

    def generate_heightmap(self):
        def perlin_noise(x, y, seed=42):
            def lerp(a, b, x):
                return a + x * (b - a)

            random.seed(seed)
            grid_x, grid_y = int(x), int(y)
            dx, dy = x - grid_x, y - grid_y

            n00 = random.uniform(-1, 1)
            n10 = random.uniform(-1, 1)
            n01 = random.uniform(-1, 1)
            n11 = random.uniform(-1, 1)

            x0 = n00 * (1 - dx) + n10 * dx
            x1 = n01 * (1 - dx) + n11 * dx
            return lerp(x0, x1, dy)

        self.heightmap = np.zeros((100, 100), dtype=np.float32)
        for x in range(100):
            for y in range(100):
                self.heightmap[x, y] = perlin_noise(x/20, y/20) * 10

    def setup_shader_programs(self):
        vertex_shader = """
            #version 330
            uniform mat4 model;
            uniform mat4 view;
            uniform mat4 projection;

            in vec3 position;
            in vec3 normal;

            out vec3 fragNormal;
            out vec3 fragPosition;

            void main() {
                fragPosition = vec3(model * vec4(position, 1.0));
                fragNormal = mat3(model) * normal;
                gl_Position = projection * view * vec4(fragPosition, 1.0);
            }
        """

        fragment_shader = """
            #version 330
            uniform vec3 lightPositions[7];
            uniform vec3 lightColors[7];

            in vec3 fragNormal;
            in vec3 fragPosition;

            out vec4 outColor;

            void main() {
                vec3 normal = normalize(fragNormal);
                vec3 totalLight = vec3(0.1);

                for(int i = 0; i < 7; i++) {
                    vec3 lightDir = normalize(lightPositions[i] - fragPosition);
                    float diff = max(dot(normal, lightDir), 0.0);
                    totalLight += diff * lightColors[i];
                }

                outColor = vec4(totalLight, 1.0);
            }
        """

        self.prog = self.ctx.program(
            vertex_shader=vertex_shader,
            fragment_shader=fragment_shader
        )

    def create_light_sources(self):
        self.light_positions = [
            glm.vec3(random.uniform(-50, 50), 20, random.uniform(-50, 50))
            for _ in range(7)
        ]
        self.light_colors = [
            glm.vec3(random.random(), random.random(), random.random())
            for _ in range(7)
        ]

    def setup_camera(self):
        self.view = glm.lookAt(
            glm.vec3(50, 50, 100),
            glm.vec3(0, 0, 0),
            glm.vec3(0, 1, 0)
        )
        self.projection = glm.perspective(45, self.width/self.height, 0.1, 1000.0)

    def update_light_positions(self, time):
        for i in range(7):
            radius = 50
            angle = time + i * (2 * math.pi / 7)
            self.light_positions[i].x = radius * math.cos(angle)
            self.light_positions[i].z = radius * math.sin(angle)

    def render(self):
        running = True
        clock = pygame.time.Clock()

        while running:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    running = False

            time = pygame.time.get_ticks() * 0.001
            self.update_light_positions(time)

            self.ctx.clear(0.2, 0.2, 0.2)

            # Render logic here (simplified)
            clock.tick(60)
            pygame.display.flip()

        pygame.quit()

if __name__ == "__main__":
    renderer = TerrainLightRenderer()
    renderer.render()

