import eventlet.green.urllib2 as urllib2
from urllib import quote
import config

class TwitterStreamProcessor:
    def __init__(self, track_queries, languages=None):
        self.consumer_key = config.CONSUMER_KEY
        self.consumer_secret = config.CONSUMER_SECRET
        self.access_token = config.ACCESS_TOKEN
        self.access_token_secret = config.ACCESS_TOKEN_SECRET

        self.track_queries = [q.lower() for q in track_queries]
        self.languages = languages or ['en']
        self.tweet_queue = []

        self._auth_headers = self._generate_oauth_headers()

    def _generate_oauth_headers(self):
        oauth_base = {
            'oauth_consumer_key': self.consumer_key,
            'oauth_nonce': str(int(time.time() * 1000)),
            'oauth_signature_method': 'HMAC-SHA1',
            'oauth_timestamp': str(int(time.time())),
            'oauth_token': self.access_token,
            'oauth_version': '1.0'
        }

        # Advanced OAuth signature generation logic
        encoded_params = urllib2.quote(json.dumps(oauth_base), safe='')
        auth_header = 'OAuth ' + ', '.join([
            f'{quote(k)}="{quote(str(v))}"' 
            for k, v in oauth_base.items()
        ])

        return {'Authorization': auth_header}

    def _parse_tweet_metadata(self, tweet_data):
        try:
            parsed_tweet = {
                'id': tweet_data.get('id_str', ''),
                'text': tweet_data.get('text', ''),
                'created_at': self._parse_timestamp(tweet_data.get('created_at', '')),
                'user': {
                    'id': tweet_data.get('user', {}).get('id_str', ''),
                    'screen_name': tweet_data.get('user', {}).get('screen_name', ''),
                    'followers_count': tweet_data.get('user', {}).get('followers_count', 0)
                },
                'language': tweet_data.get('lang', ''),
                'metadata': {
                    'retweet_count': tweet_data.get('retweet_count', 0),
                    'favorite_count': tweet_data.get('favorite_count', 0)
                }
            }
            return parsed_tweet
        except Exception as e:
            print(f"Tweet parsing error: {e}")
            return None

    def _parse_timestamp(self, timestamp_str):
        try:
            return int(time.mktime(time.strptime(timestamp_str, '%a %b %d %H:%M:%S +0000 %Y')))
        except ValueError:
            return int(time.time())

    def _query_matches(self, tweet_text):
        tweet_text = tweet_text.lower()
        return any(query in tweet_text for query in self.track_queries)

    def stream(self):
        url = 'https://stream.twitter.com/1.1/statuses/filter.json'
        post_data = {
            'track': ','.join(self.track_queries),
            'language': ','.join(self.languages)
        }

        try:
            request = urllib2.Request(url, data=urllib2.urlencode(post_data))
            request.headers.update(self._auth_headers)

            response = urllib2.urlopen(request)

            for line in response:
                if line.strip():
                    try:
                        tweet_data = json.loads(line)

                        if (tweet_data.get('lang') in self.languages and 
                            self._query_matches(tweet_data.get('text', ''))):

                            processed_tweet = self._parse_tweet_metadata(tweet_data)

                            if processed_tweet:
                                self.tweet_queue.append(processed_tweet)

                                if len(self.tweet_queue) > 100:
                                    self.tweet_queue.pop(0)

                    except json.JSONDecodeError:
                        continue

        except Exception as e:
            print(f"Stream connection error: {e}")

    def get_tweets(self):
        tweets = self.tweet_queue.copy()
        self.tweet_queue.clear()
        return tweets

# Usage Example
if __name__ == "__main__":
    queries = ['python', 'data science', 'machine learning']
    stream_processor = TwitterStreamProcessor(queries, ['en'])
    stream_processor.stream()

from collections import namedtuple
import os
import sys

Resolution = namedtuple('Resolution', ['width', 'height'])

class Resolutions:
    SUPPORTED = [
        Resolution(1280, 720),
        Resolution(1600, 900),
        Resolution(1920, 1080),
        Resolution(2560, 1440)
    ]

    @classmethod
    def validate(cls, resolution):
        return resolution in cls.SUPPORTED

class Color:
    def __init__(self, r, g, b):
        self.validate(r, g, b)
        self.r, self.g, self.b = r, g, b

    def validate(self, r, g, b):
        for value in (r, g, b):
            if not (0 <= value <= 255):
                raise ValueError(f"Invalid color value: {value}")

    @classmethod
    def parse(cls, color_str):
        try:
            r, g, b = map(int, color_str.split(','))
            return cls(r, g, b)
        except (ValueError, TypeError):
            raise ValueError(f"Invalid color format: {color_str}")

class DisplayConfig:
    DEFAULT_CONFIG = {
        'NUM_CELLS': 16,
        'RESOLUTION': Resolution(1920, 1080),
        'PIXEL_PER_CELL': 50,
        'OFFSET_X': 10,
        'OFFSET_Y': 10,
        'GRID_COLOR': Color(200, 200, 200),
        'BACKGROUND_COLOR': Color(50, 50, 50)
    }

    @staticmethod
    def read_config(filepath='config.cfg'):
        if not os.path.exists(filepath):
            return DisplayConfig.DEFAULT_CONFIG

        config = DisplayConfig.DEFAULT_CONFIG.copy()
        try:
            with open(filepath, 'r') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue

                    key, value = line.split('=', 1)
                    key = key.strip()
                    value = value.strip()

                    config[key] = DisplayConfig.try_parse(key, value)
        except Exception as e:
            print(f"Config parsing error: {e}")
            return DisplayConfig.DEFAULT_CONFIG

        return config

    @staticmethod
    def try_parse(key, value):
        if key == 'RESOLUTION':
            try:
                w, h = map(int, value.split('x'))
                resolution = Resolution(w, h)
                if not Resolutions.validate(resolution):
                    raise ValueError(f"Unsupported resolution: {resolution}")
                return resolution
            except ValueError:
                print(f"Invalid resolution: {value}. Using default.")
                return DisplayConfig.DEFAULT_CONFIG['RESOLUTION']

        if key in ['NUM_CELLS', 'PIXEL_PER_CELL', 'OFFSET_X', 'OFFSET_Y']:
            return int(value)

        if key.endswith('_COLOR'):
            return Color.parse(value)

        return value

    @staticmethod
    def validate_config(config):
        required_keys = [
            'NUM_CELLS', 'RESOLUTION', 'PIXEL_PER_CELL', 
            'OFFSET_X', 'OFFSET_Y', 'GRID_COLOR', 'BACKGROUND_COLOR'
        ]

        for key in required_keys:
            if key not in config:
                raise KeyError(f"Missing configuration key: {key}")

def main():
    try:
        config = DisplayConfig.read_config()
        DisplayConfig.validate_config(config)
        print("Configuration loaded successfully.")
    except Exception as e:
        print(f"Configuration error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

from django import forms
from django.utils.translation import ugettext_lazy as _
from django.core.exceptions import ValidationError

class DiscountPricingForm(forms.Form):
    def __init__(self, *args, **kwargs):
        self.product = kwargs.pop('product', None)
        self.shops = kwargs.pop('shops', [])
        super(DiscountPricingForm, self).__init__(*args, **kwargs)
        self._build_fields()

    def _build_fields(self):
        for shop in self.shops:
            field_name = self._get_field_name(shop)
            self.fields[field_name] = forms.DecimalField(
                label=_("Price for %s") % shop.name,
                required=False,
                min_value=0,
                decimal_places=2,
                max_digits=12,
                initial=self._get_initial_price(shop)
            )

    def _get_field_name(self, shop):
        return f'discount_price_{shop.pk}'

    def _get_initial_price(self, shop):
        from your_pricing_module import get_product_discount_price
        price = get_product_discount_price(self.product, shop)
        return price.amount if price else None

    def clean(self):
        cleaned_data = super().clean()
        for shop in self.shops:
            field_name = self._get_field_name(shop)
            price = cleaned_data.get(field_name)

            if price is not None and price <= 0:
                cleaned_data[field_name] = None

        return cleaned_data

    def save(self):
        from your_pricing_module import update_product_price

        for shop in self.shops:
            field_name = self._get_field_name(shop)
            price = self.cleaned_data.get(field_name)

            if price is None:
                self._process_single_clear(shop)
            else:
                self._process_single_save(shop, price)

    def _process_single_save(self, shop, price):
        try:
            update_product_price(
                product=self.product,
                shop=shop,
                price=price
            )
        except ValidationError as e:
            self.add_error(self._get_field_name(shop), e)

    def _process_single_clear(self, shop):
        try:
            update_product_price(
                product=self.product,
                shop=shop,
                price=None
            )
        except ValidationError as e:
            self.add_error(self._get_field_name(shop), e)

    @classmethod
    def get_shop_field(cls, shop):
        """Utility method for generating individual shop pricing fields."""
        return forms.DecimalField(
            label=_("Price for %s") % shop.name,
            required=False,
            min_value=0,
            decimal_places=2,
            max_digits=12
        )

class DiscountPricingFormPart:
    """Form part for integrating discount pricing into complex forms."""

    def get_form_part(self, request):
        shops = request.shop_context.shops
        return DiscountPricingForm(
            product=self.object,
            shops=shops
        )

    def form_valid(self, form):
        """Extended form validation for pricing integration."""
        result = super().form_valid(form)

        if hasattr(form, 'save'):
            form.save()

        return result

import socket
import telnetlib
import ftplib
import sys
import os
import re

class ParrotDroneManager:
    def __init__(self, host):
        self.host = host
        self.tn = None
        self.ftp = None
        self.port = 23

    def is_ip(self, address):
        """Validate IP address format."""
        pattern = r'^(\d{1,3}\.){3}\d{1,3}$'
        return re.match(pattern, address) is not None

    def split_into_path_and_file(self, filepath):
        """Split full filepath into directory and filename."""
        return os.path.split(filepath)

    def connect(self):
        """Establish telnet connection to drone."""
        try:
            if not self.is_ip(self.host):
                raise ValueError("Invalid IP address")

            self.tn = telnetlib.Telnet(self.host, self.port)
            self.tn.read_until(b"login: ")
            self.tn.write(b"root\n")
            return True
        except Exception as e:
            print(f"Connection error: {e}")
            return False

    def execute_command(self, command):
        """Execute remote command via telnet."""
        try:
            if not self.tn:
                raise ConnectionError("Telnet not connected")

            self.tn.write(command.encode('ascii') + b'\n')
            response = self.tn.read_until(b"# ", timeout=5).decode('ascii')
            return response
        except Exception as e:
            print(f"Command execution error: {e}")
            return None

    def check_version(self):
        """Retrieve drone system version."""
        return self.execute_command("cat /etc/version")

    def check_running(self):
        """List running processes."""
        return self.execute_command("ps aux")

    def check_filesystem(self):
        """Check filesystem status and free space."""
        return self.execute_command("df -h")

    def reboot(self):
        """Initiate drone system reboot."""
        try:
            self.execute_command("reboot")
            return True
        except Exception as e:
            print(f"Reboot error: {e}")
            return False

    def uploadfile(self, local_file, remote_path):
        """Upload file to drone via FTP."""
        try:
            self.ftp = ftplib.FTP(self.host)
            self.ftp.login(user='anonymous', passwd='')

            directory, filename = self.split_into_path_and_file(local_file)

            with open(local_file, 'rb') as file:
                self.ftp.storbinary(f'STOR {remote_path}/{filename}', file)

            return True
        except Exception as e:
            print(f"File upload error: {e}")
            return False
        finally:
            if self.ftp:
                self.ftp.quit()

    def disconnect(self):
        """Close telnet connection."""
        try:
            if self.tn:
                self.tn.close()
            if self.ftp:
                self.ftp.quit()
        except Exception as e:
            print(f"Disconnection error: {e}")

def main():
    if len(sys.argv) < 2:
        print("Usage: drone_manager.py <drone_ip>")
        sys.exit(1)

    drone_ip = sys.argv[1]
    drone_manager = ParrotDroneManager(drone_ip)

    if drone_manager.connect():
        print("Successfully connected to drone")

        # Perform diagnostic checks
        print("System Version:", drone_manager.check_version())
        print("Running Processes:", drone_manager.check_running())
        print("Filesystem Status:", drone_manager.check_filesystem())

        # Optionally upload file
        # drone_manager.uploadfile('/path/local/file', '/remote/path')

        drone_manager.disconnect()
    else:
        print("Failed to connect to drone")

if __name__ == "__main__":
    main()

