    comm = wkpfcomm.WKPFComm()
    return comm

def getNodeIds():
    """Return list of predefined node identifiers."""
    return [2, 4, 5, 6, 7, 10, 12, 13, 14, 15]

def setFeature(comm, node_id, feature_type, feature_value):
    """Configure specific feature for a given node."""
    try:
        comm.setComponentProperty(node_id, feature_type, feature_value)
    except Exception as e:
        print(f"Error setting feature for node {node_id}: {e}")

def setLocation(comm, node_id, x, y, z):
    """Set location coordinates for a specific node."""
    try:
        comm.setLocationProperty(node_id, x, y, z)
    except Exception as e:
        print(f"Error setting location for node {node_id}: {e}")

def configureNetworkNodes():
    """Configure and initialize network nodes with specific settings."""
    comm = getComm()
    node_ids = getNodeIds()

    for node_id in node_ids:
        # Light Sensor Configuration
        setFeature(comm, node_id, 'light_sensor_threshold', 500)
        setFeature(comm, node_id, 'light_sensor_type', 'digital')

        # Light Actuator Configuration
        setFeature(comm, node_id, 'light_actuator_mode', 'auto')
        setFeature(comm, node_id, 'light_actuator_range', 100)

        # Numeric Controller Settings
        setFeature(comm, node_id, 'numeric_controller_min', 0)
        setFeature(comm, node_id, 'numeric_controller_max', 1000)

