import os
import logging
import tempfile
from xml.dom import minidom
from zeroinstall.injector import model
from zeroinstall.injector.namespaces import XMLNS_IFACE

class ZeroInstallXMLValidator:
    def __init__(self, logger=None):
        self.logger = logger or logging.getLogger(__name__)
        self.known_elements = {
            'interface': ['uri', 'name', 'summary', 'description'],
            'group': ['id', 'arch', 'stability', 'version'],
            'implementation': ['id', 'version', 'released']
        }
        self.group_impl_attribs = [
            'id', 'arch', 'version', 'stability', 
            'main', 'self-test', 'download-size'
        ]

    def check_element(self, element):
        """
        Recursively validate XML element structure and attributes
        """
        try:
            element_name = element.tagName
            if element_name not in self.known_elements:
                self.logger.warning(f"Unknown element: {element_name}")
                return False

            allowed_attrs = self.known_elements.get(element_name, [])
            for attr in element.attributes.keys():
                if attr not in allowed_attrs:
                    self.logger.warning(f"Unexpected attribute in {element_name}: {attr}")

            for child in element.childNodes:
                if child.nodeType == child.ELEMENT_NODE:
                    self.check_element(child)

            return True
        except Exception as e:
            self.logger.error(f"Element validation error: {e}")
            return False

    def check(self, xml_doc):
        """
        Primary validation method for XML document
        """
        try:
            root_element = xml_doc.documentElement
            return self.check_element(root_element)
        except Exception as e:
            self.logger.critical(f"XML document validation failed: {e}")
            return False

    def load_feed(self, xml_path):
        """
        Load and parse Zero Install XML feed
        """
        try:
            with tempfile.NamedTemporaryFile(delete=False, mode='w+') as temp_file:
                temp_path = temp_file.name

            try:
                xml_doc = minidom.parse(xml_path)
                if not self.check(xml_doc):
                    raise ValueError("XML validation failed")

                feed = model.Feed(xml_path)
                feed.load()
                return feed

            except Exception as e:
                self.logger.error(f"Feed loading error: {e}")
                return None
            finally:
                if os.path.exists(temp_path):
                    os.unlink(temp_path)

        except IOError as io_err:
            self.logger.error(f"File handling error: {io_err}")
            return None

    def validate_namespace(self, xml_doc):
        """
        Check XML namespace compliance
        """
        try:
            root_element = xml_doc.documentElement
            namespace = root_element.namespaceURI
            return namespace == XMLNS_IFACE
        except Exception as e:
            self.logger.warning(f"Namespace validation error: {e}")
            return False

    def extract_metadata(self, xml_doc):
        """
        Extract key metadata from validated XML
        """
        try:
            root = xml_doc.documentElement
            metadata = {
                'uri': root.getAttribute('uri') if root.hasAttribute('uri') else None,
                'name': root.getAttribute('name') if root.hasAttribute('name') else None,
                'summary': self._get_text_content(root, 'summary'),
                'implementations': self._parse_implementations(root)
            }
            return metadata
        except Exception as e:
            self.logger.error(f"Metadata extraction error: {e}")
            return None

    def _get_text_content(self, element, tag_name):
        """
        Helper method to retrieve text content of a specific tag
        """
        try:
            elements = element.getElementsByTagName(tag_name)
            return elements[0].firstChild.nodeValue if elements and elements[0].firstChild else None
        except Exception:
            return None

    def _parse_implementations(self, root_element):
        """
        Parse implementation details from XML
        """
        implementations = []
        impl_elements = root_element.getElementsByTagName('implementation')

        for impl in impl_elements:
            impl_data = {attr: impl.getAttribute(attr) for attr in self.group_impl_attribs if impl.hasAttribute(attr)}
            implementations.append(impl_data)

        return implementations

