class Bear:
    def __init__(self, lamak, others):
        self.lamak = lamak
        self.srt = sorted(others)
        self.result = 0

    def calculate(self):
        while self.srt and self.lamak <= max(self.srt):
            max_bear = max(self.srt)
            max_idx = self.srt.index(max_bear)

            self.srt[max_idx] -= 1
            self.lamak += 1
            self.result += 1

            self.srt.sort()

        return self.result

