class Computer:
    def __init__(self, instructions):
        self.instructions = instructions
        self.registers = {'a': 0, 'b': 0}
        self.ip = 0

    def hlf(self, reg):
        self.registers[reg] //= 2
        self.ip += 1

    def tpl(self, reg):
        self.registers[reg] *= 3
        self.ip += 1

    def inc(self, reg):
        self.registers[reg] += 1
        self.ip += 1

    def jmp(self, offset):
        self.ip += offset

    def jie(self, reg, offset):
        if self.registers[reg] % 2 == 0:
            self.ip += offset
        else:
            self.ip += 1

    def jio(self, reg, offset):
        if self.registers[reg] == 1:
            self.ip += offset
        else:
            self.ip += 1

    def parse_instruction(self, instruction):
        parts = instruction.replace(',', '').split()
        return parts[0], parts[1:] if len(parts) > 1 else []

    def run_program(self):
        while 0 <= self.ip < len(self.instructions):
            current_instruction = self.instructions[self.ip]
            op, args = self.parse_instruction(current_instruction)

            method_map = {
                'hlf': self.hlf,
                'tpl': self.tpl,
                'inc': self.inc,
                'jmp': self.jmp,
                'jie': self.jie,
                'jio': self.jio
            }

            if op in method_map:
                if op == 'jmp':
                    method_map[op](int(args[0]))
                elif op in ['hlf', 'tpl', 'inc']:
                    method_map[op](args[0])
                elif op in ['jie', 'jio']:
                    method_map[op](args[0], int(args[1]))
                else:
                    self.ip += 1
            else:
                break

def solve_puzzle1(instructions):
    computer = Computer(instructions)
    computer.run_program()
    return computer.registers['b']

def solve_puzzle2(instructions):
    computer = Computer(instructions)
    computer.registers['a'] = 1
    computer.run_program()
    return computer.registers['b']

def read_input(filename):
    with open(filename, 'r') as f:
        return [line.strip() for line in f.readlines()]

def main():
    instructions = read_input('input.txt')

    result1 = solve_puzzle1(instructions)
    print(f"Puzzle 1 Result: {result1}")

    result2 = solve_puzzle2(instructions)
    print(f"Puzzle 2 Result: {result2}")

if __name__ == "__main__":
    main()

import re
import json
import xml.etree.ElementTree as ET
from urllib.parse import urljoin, urlparse
import base64

class TNAFlixIE:
    _VALID_URL = r'https?://(?:www\.)?tnaf\d+\.(?:com|net)/video/(\d+)'
    _CONFIG_REGEX = r'var\s+config\s*=\s*({.*?});'
    _TITLE_REGEX = r'<h1[^>]*>(.+?)</h1>'
    _DESCRIPTION_REGEX = r'<div[^>]*class="description"[^>]*>(.+?)</div>'

    def __init__(self, url):
        self.url = url
        self.video_id = None
        self.webpage = None
        self.cfg_xml = None
        self.formats = []

    def _download_webpage(self):
        try:
            # Simulated webpage download
            import urllib.request
            headers = {
                'User-Agent': 'Mozilla/5.0',
                'Cookie': 'age_verified=true'
            }
            request = urllib.request.Request(self.url, headers=headers)
            response = urllib.request.urlopen(request)
            self.webpage = response.read().decode('utf-8')
        except Exception as e:
            raise Exception(f"Webpage download failed: {e}")

    def _download_xml(self, config_url):
        try:
            import urllib.request
            response = urllib.request.urlopen(config_url)
            self.cfg_xml = response.read().decode('utf-8')
        except Exception as e:
            raise Exception(f"XML download failed: {e}")

    def _html_search_regex(self, pattern, default=None):
        match = re.search(pattern, self.webpage, re.DOTALL)
        return match.group(1) if match else default

    def _extract_config(self):
        match = re.search(self._CONFIG_REGEX, self.webpage, re.DOTALL)
        if match:
            try:
                config = json.loads(match.group(1))
                return config
            except json.JSONDecodeError:
                return None
        return None

    def _extract_formats(self, config):
        formats = []
        if config and 'sources' in config:
            for source in config['sources']:
                format_entry = {
                    'url': source.get('file', ''),
                    'height': source.get('height', 0),
                    'width': source.get('width', 0),
                    'ext': source.get('type', '').split('/')[-1]
                }
                formats.append(format_entry)
        return formats

    def _sort_formats(self):
        self.formats.sort(key=lambda x: x.get('height', 0), reverse=True)

    def _extract_thumbnail(self, config):
        return config.get('image', '') if config else ''

    def _parse_duration(self, config):
        duration = config.get('duration', 0)
        return int(duration)

    def _real_extract(self):
        # Validate URL
        match = re.match(self._VALID_URL, self.url)
        if not match:
            raise ValueError("Invalid TNAFlix URL")

        self.video_id = match.group(1)

        # Download webpage
        self._download_webpage()

        # Extract configuration
        config = self._extract_config()
        if not config:
            raise Exception("Unable to extract video configuration")

        # Extract metadata
        metadata = {
            'id': self.video_id,
            'title': self._html_search_regex(self._TITLE_REGEX, 'Untitled'),
            'description': self._html_search_regex(self._DESCRIPTION_REGEX, ''),
            'thumbnail': self._extract_thumbnail(config),
            'duration': self._parse_duration(config)
        }

        # Extract formats
        self.formats = self._extract_formats(config)
        self._sort_formats()

        # Return complete video information
        return {
            **metadata,
            'formats': self.formats
        }

def main():
    url = 'https://tnaf123.com/video/12345'
    extractor = TNAFlixIE(url)
    try:
        video_info = extractor._real_extract()
        print(json.dumps(video_info, indent=2))
    except Exception as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    main()

import unittest
import sqlite3
import json

class Foo:
    def __init__(self, id, name, data):
        self.id = id
        self.name = name
        self.data = data

def connect():
    return sqlite3.connect(':memory:')

def create_table(conn, table_name, columns):
    column_definitions = ', '.join(f"{col} {dtype}" for col, dtype in columns.items())
    conn.execute(f"CREATE TABLE {table_name} ({column_definitions})")
    conn.commit()

def insert_all(conn, table_name, records):
    if not records:
        return

    columns = list(records[0].keys())
    placeholders = ', '.join(['?' for _ in columns])
    query = f"INSERT INTO {table_name} ({', '.join(columns)}) VALUES ({placeholders})"

    values = [
        [record.get(col, None) for col in columns]
        for record in records
    ]
    conn.executemany(query, values)
    conn.commit()

def json_get(json_data, path, default=None):
    try:
        if not json_data:
            return default

        parsed_data = json.loads(json_data) if isinstance(json_data, str) else json_data

        for key in path.split('.'):
            if isinstance(parsed_data, dict):
                parsed_data = parsed_data.get(key)
            elif isinstance(parsed_data, list) and key.isdigit():
                parsed_data = parsed_data[int(key)] if 0 <= int(key) < len(parsed_data) else None
            else:
                return default

            if parsed_data is None:
                return default

        return parsed_data
    except (json.JSONDecodeError, TypeError, IndexError):
        return default

class TestSqliteUtil(unittest.TestCase):
    def setUp(self):
        self.conn = connect()

    def tearDown(self):
        self.conn.close()

    def test_create_table(self):
        columns = {
            'id': 'INTEGER PRIMARY KEY',
            'name': 'TEXT',
            'data': 'TEXT'
        }
        create_table(self.conn, 'users', columns)

        cursor = self.conn.execute("PRAGMA table_info(users)")
        columns_info = cursor.fetchall()

        self.assertEqual(len(columns_info), 3)
        self.assertEqual(columns_info[0][1], 'id')
        self.assertEqual(columns_info[1][1], 'name')
        self.assertEqual(columns_info[2][1], 'data')

    def test_insert_all(self):
