import numpy as np
import sys
import os
from typing import List, Dict, Union, Optional

class CharToIntArrayMapping:
    def __init__(self, mapping_dict: Optional[Dict[str, int]] = None):
        self.mapping_dict = mapping_dict or {}
        self.default_value = -1

    def map_char_to_int(self, char: str) -> int:
        """Map a single character to its integer representation."""
        char = char.upper()
        return self.mapping_dict.get(char, self.default_value)

    def map_sequence(self, sequence: str) -> List[int]:
        """Convert entire sequence to integer array."""
        return [self.map_char_to_int(char) for char in sequence.upper()]

    @classmethod
    def from_file(cls, filename: str) -> 'CharToIntArrayMapping':
        """Create mapping from configuration file."""
        mapping_dict = {}
        try:
            with open(filename, 'r') as f:
                for line in f:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        parts = line.split()
                        if len(parts) >= 2:
                            mapping_dict[parts[0].upper()] = int(parts[1])
        except FileNotFoundError:
            print(f"Warning: Mapping file {filename} not found.")

        return cls(mapping_dict)

    def add_mapping(self, char: str, value: int) -> None:
        """Add or update a mapping for a specific character."""
        self.mapping_dict[char.upper()] = value

class IntToIntMapping:
    def __init__(self, mapping_dict: Optional[Dict[int, int]] = None):
        self.mapping_dict = mapping_dict or {}
        self.default_value = -1

    def map_int_to_int(self, value: int) -> int:
        """Map an integer to another integer."""
        return self.mapping_dict.get(value, self.default_value)

    def map_sequence(self, sequence: List[int]) -> List[int]:
        """Transform entire integer sequence."""
        return [self.map_int_to_int(val) for val in sequence]

    @classmethod
    def from_file(cls, filename: str) -> 'IntToIntMapping':
        """Create integer mapping from configuration file."""
        mapping_dict = {}
        try:
            with open(filename, 'r') as f:
                for line in f:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        parts = line.split()
                        if len(parts) >= 2:
                            mapping_dict[int(parts[0])] = int(parts[1])
        except FileNotFoundError:
            print(f"Warning: Mapping file {filename} not found.")

        return cls(mapping_dict)

    def identity_mapping(self, max_value: int) -> None:
        """Create an identity mapping for values up to max_value."""
        self.mapping_dict = {i: i for i in range(max_value + 1)}

def alignment_mapping_from_file(char_mapping_file: str, 
                                 int_mapping_file: Optional[str] = None) -> tuple:
    """Generate comprehensive sequence mapping from files."""
    char_mapper = CharToIntArrayMapping.from_file(char_mapping_file)

    if int_mapping_file:
        int_mapper = IntToIntMapping.from_file(int_mapping_file)
    else:
        int_mapper = IntToIntMapping()

    return char_mapper, int_mapper

def process_genomic_sequence(sequence: str, 
                             char_mapper: CharToIntArrayMapping, 
                             int_mapper: Optional[IntToIntMapping] = None) -> List[int]:
    """Convert genomic sequence using specified mappers."""
    initial_mapping = char_mapper.map_sequence(sequence)

    if int_mapper:
        return int_mapper.map_sequence(initial_mapping)

    return initial_mapping

def validate_mapping_configuration(mapping_config: Dict[str, Union[str, int]]) -> bool:
    """Validate mapping configuration parameters."""
    required_keys = ['char_mapping_file', 'sequence_type']
    return all(key in mapping_config for key in required_keys)

def generate_dna_default_mapping() -> CharToIntArrayMapping:
    """Create default DNA base mapping."""
    default_dna_mapping = {
        'A': 0, 'C': 1, 'G': 2, 'T': 3,
        'N': 4, '-': 5
    }
    return CharToIntArrayMapping(default_dna_mapping)

import dns.message
import dns.query
import dns.rdatatype
import socket
import struct
import os
import threading
import time
import random
import ipaddress

class testKeepOpenTCP:
    def __init__(self, resolver_addr, port=53):
        self.resolver_addr = resolver_addr
        self.port = port
        self.timeout = 5.0
        self.max_connections = 10

    def generateRecursorConfig(self):
        config = {
            'dnssec': True,
            'tcp_keepalive': True,
            'max_udp_size': 4096,
            'timeout': self.timeout
        }
        return config

    def sendTCPQueryKeepOpen(self, domain, query_type):
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(self.timeout)
            sock.connect((self.resolver_addr, self.port))

            query = dns.message.make_query(domain, query_type, want_dnssec=True)
            wire_query = query.to_wire()

            # Send DNS query length prefix
            sock.sendall(struct.pack('!H', len(wire_query)))
            sock.sendall(wire_query)

            # Receive response length prefix
            response_len = struct.unpack('!H', sock.recv(2))[0]
            response_data = sock.recv(response_len)

            response = dns.message.from_wire(response_data)
            return response, sock

        except Exception as e:
            print(f"TCP Query Error: {e}")
            return None, None

    def testNoTrailingData(self, domain, query_type):
        responses = []
        sockets = []

        for _ in range(self.max_connections):
            response, sock = self.sendTCPQueryKeepOpen(domain, query_type)
            if response is not None:
                responses.append(response)
                sockets.append(sock)

        # Validate DNSSEC and check no trailing data
        for response in responses:
            if response.rcode() != dns.rcode.NOERROR:
                return False

            if not response.is_response():
                return False

            # Optional DNSSEC validation logic
            if not self._validateDNSSEC(response):
                return False

        # Close all sockets properly
        for sock in sockets:
            try:
                sock.close()
            except Exception:
                pass

        return True

    def _validateDNSSEC(self, response):
        # Simplified DNSSEC validation
        try:
            dnssec_records = response.get_rrset(response.authority, dns.rdatatype.RRSIG)
            return dnssec_records is not None
        except Exception:
            return False

    def runTest(self):
        test_domains = [
            'example.com',
            'google.com',
            'cloudflare.com'
        ]
        query_types = [
            dns.rdatatype.A,
            dns.rdatatype.AAAA,
            dns.rdatatype.MX
        ]

        results = []
        for domain in test_domains:
            for query_type in query_types:
                result = self.testNoTrailingData(domain, query_type)
                results.append(result)

        return all(results)

def main():
    resolver_test = testKeepOpenTCP('127.0.0.1')
    test_result = resolver_test.runTest()
    print(f"DNS TCP Connection Test Result: {test_result}")

if __name__ == '__main__':
    main()

import numpy as np
import pyspeckit
from astropy.table import Table
from astropy.io import fits
import matplotlib.pyplot as plt
import glob
import os

class SpectralAnalyzer:
    def __init__(self, data_directory):
        self.data_directory = data_directory
        self.observation_files = []
        self.data_collection = {}
        self.results_table = None

    def find_observation_files(self, file_pattern='*.fits'):
        self.observation_files = glob.glob(os.path.join(self.data_directory, file_pattern))

    def is_scientific_source(self, source_name):
        excluded_sources = ['NOISE', 'CALIBRATOR', 'SKY']
        return not any(excluded in source_name.upper() for excluded in excluded_sources)

    def read_spectral_data(self):
        for filepath in self.observation_files:
            try:
                spec_data = pyspeckit.Spectrum(filepath)
                source_name = spec_data.header.get('OBJECT', 'UNKNOWN')
                telescope = spec_data.header.get('TELESCOP', 'UNKNOWN')

                if self.is_scientific_source(source_name):
                    if source_name not in self.data_collection:
                        self.data_collection[source_name] = {}

                    self.data_collection[source_name][telescope] = {
                        'spectrum': spec_data.data,
                        'frequency': spec_data.xarr,
                        'tsys': spec_data.header.get('TSYS', np.nan),
                        'rms': np.nanstd(spec_data.data)
                    }
            except Exception as e:
                print(f"Error processing {filepath}: {e}")

    def compute_statistical_metrics(self):
        metrics = {}
        for source, telescope_data in self.data_collection.items():
            metrics[source] = {}
            for telescope, data in telescope_data.items():
                metrics[source][telescope] = {
                    'mean_tsys': data['tsys'],
                    'rms_std': data['rms']
                }
        return metrics

    def create_results_table(self, metrics):
        table_data = []
        for source, telescope_data in metrics.items():
            for telescope, measurement in telescope_data.items():
                table_data.append([
                    source, 
                    telescope, 
                    measurement['mean_tsys'], 
                    measurement['rms_std']
                ])

        self.results_table = Table(
            rows=table_data, 
            names=['Source', 'Telescope', 'Tsys', 'RMS_Std']
        )

    def visualize_tsys_distribution(self):
        if self.results_table is None:
            return

        plt.figure(figsize=(10, 6))
        plt.scatter(
            self.results_table['Tsys'], 
            self.results_table['RMS_Std'], 
            c=self.results_table['Tsys'], 
            cmap='viridis'
        )
        plt.xlabel('System Temperature (K)')
        plt.ylabel('RMS Standard Deviation')
        plt.title('Tsys vs RMS Std Distribution')
        plt.colorbar(label='Tsys')
        plt.tight_layout()
        plt.show()

    def export_results(self, output_path='spectral_analysis_results.fits'):
        if self.results_table is not None:
            self.results_table.write(output_path, overwrite=True)

    def run_analysis(self):
        self.find_observation_files()
        self.read_spectral_data()
        metrics = self.compute_statistical_metrics()
        self.create_results_table(metrics)
        self.visualize_tsys_distribution()
        self.export_results()

def main():
    analyzer = SpectralAnalyzer('/path/to/observation/data')
    analyzer.run_analysis()

if __name__ == '__main__':
    main()

import json
import lxml.etree as ET
from django.contrib.auth.models import User, Group, Permission
from django.contrib.contenttypes.models import ContentType
from django.core.cache import cache
