import osv
from tools.translate import _

class event_confirm_registration(osv.TransientModel):
    _name = 'event.confirm.registration'
    _description = 'Event Registration Confirmation'

    def _get_registration_warning(self, cr, uid, context=None):
        if context is None:
            context = {}

        registration_ids = context.get('active_ids', [])
        event_obj = self.pool.get('event.event')
        registration_obj = self.pool.get('event.registration')

        msg = ''
        for registration in registration_obj.browse(cr, uid, registration_ids, context=context):
            event = registration.event_id

            if event.register_max and event.register_current >= event.register_max:
                msg += _("Event '%s' has reached its maximum registration limit.\n") % event.name

        return msg

    _columns = {
        'registration_ids': fields.many2many(
            'event.registration', 
            'event_confirm_registration_rel', 
            'wizard_id', 
            'registration_id', 
            string='Registrations'
        ),
        'confirm_registration': fields.boolean(
            'Confirm Registrations', 
            help='Confirm registrations despite reaching event capacity'
        ),
        'warning_message': fields.text(
            'Warning Message', 
            readonly=True
        )
    }

    def default_get(self, cr, uid, fields, context=None):
        if context is None:
            context = {}

        res = super(event_confirm_registration, self).default_get(cr, uid, fields, context=context)
        registration_ids = context.get('active_ids', [])

        if 'registration_ids' in fields:
            res['registration_ids'] = registration_ids

        if 'warning_message' in fields:
            warning_msg = self._get_registration_warning(cr, uid, context)
            res['warning_message'] = warning_msg

        return res

    def confirm(self, cr, uid, ids, context=None):
        if context is None:
            context = {}

        registration_obj = self.pool.get('event.registration')
        wizard = self.browse(cr, uid, ids[0], context=context)

        if wizard.confirm_registration:
            registration_obj.confirm_registration(
                cr, 
                uid, 
                wizard.registration_ids.ids, 
                context=context
            )
            return {'type': 'ir.actions.act_window_close'}
        else:
            return {
                'type': 'ir.actions.act_window_close',
                'warning': {
                    'title': _('Registration Limit Exceeded'),
                    'message': wizard.warning_message
                }
            }

    _defaults = {
        'confirm_registration': False
    }

import os
import urllib
import urllib2
import logging
from django.conf import settings
from django.contrib.sites.models import Site
from django.db.models.signals import post_save
from twitter import Api as TwitterAPI

TWITTER_MAXLENGTH = 280
logger = logging.getLogger(__name__)

def shorten_url(url):
    try:
        tiny_url = urllib2.urlopen(f"http://tinyurl.com/api-create.php?url={url}")
        return tiny_url.read().decode('utf-8')
    except Exception as e:
        logger.warning(f"URL shortening failed: {e}")
        return url

class PostUpdate:
    @classmethod
    def get_absolute_url(cls, instance):
        try:
            current_site = Site.objects.get_current()
            relative_url = instance.get_absolute_url() if hasattr(instance, 'get_absolute_url') else ''
            return f"https://{current_site.domain}{relative_url}"
        except Exception as e:
            logger.error(f"URL generation error: {e}")
            return ''

    @classmethod
    def get_twitter_message(cls, instance, absolute_url):
        try:
            if hasattr(instance, 'twitter_message'):
                custom_message = instance.twitter_message()
            else:
                default_message = f"New {instance.__class__.__name__} created: {instance}"
                custom_message = default_message

            message = f"{custom_message} {absolute_url}"

            if len(message) > TWITTER_MAXLENGTH:
                truncation_indicator = '...'
                max_text_length = TWITTER_MAXLENGTH - len(absolute_url) - len(truncation_indicator) - 1
                custom_message = custom_message[:max_text_length] + truncation_indicator
                message = f"{custom_message} {absolute_url}"

            return message
        except Exception as e:
            logger.error(f"Message generation error: {e}")
            return ''

def post_to_twitter(sender, instance, created, **kwargs):
    if not created:
        return

    try:
        twitter_consumer_key = os.environ.get('TWITTER_CONSUMER_KEY')
        twitter_consumer_secret = os.environ.get('TWITTER_CONSUMER_SECRET')
        twitter_access_token = os.environ.get('TWITTER_ACCESS_TOKEN')
        twitter_access_token_secret = os.environ.get('TWITTER_ACCESS_TOKEN_SECRET')

        if not all([twitter_consumer_key, twitter_consumer_secret, 
                    twitter_access_token, twitter_access_token_secret]):
            logger.warning("Twitter credentials not fully configured")
            return

        twitter_api = TwitterAPI(
            consumer_key=twitter_consumer_key,
            consumer_secret=twitter_consumer_secret,
            access_token_key=twitter_access_token,
            access_token_secret=twitter_access_token_secret
        )

        absolute_url = PostUpdate.get_absolute_url(instance)
        shortened_url = shorten_url(absolute_url)
        twitter_message = PostUpdate.get_twitter_message(instance, shortened_url)

        if twitter_message:
            try:
                twitter_api.PostUpdate(twitter_message)
                logger.info(f"Successfully posted Twitter update for {instance}")
            except Exception as post_error:
                logger.error(f"Twitter posting failed: {post_error}")

    except Exception as e:
        logger.error(f"Twitter update process failed: {e}")

def register_twitter_signals():
    for model in settings.TWITTER_MODELS:
        post_save.connect(post_to_twitter, sender=model)

import re
from copy import deepcopy
from sippy.SipGenericHF import SipGenericHF

class SipReplaces(SipGenericHF):
    def __init__(self, body=None, call_id=None, from_tag=None, to_tag=None, early_only=False, params=None):
        SipGenericHF.__init__(self, body)
        self.call_id = call_id
        self.from_tag = from_tag
        self.to_tag = to_tag
        self.early_only = early_only
        self.params = params or {}

        if body is not None:
            self.parse(body)

    def parse(self, body):
        body = body.strip()
        parts = body.split(';')

        # Parse main call details
        call_parts = parts[0].split(';')[0].split('%')

        try:
            self.call_id = call_parts[0]

            # Extract tags
            tag_regex = r'(from-tag|to-tag)=([^;]+)'
            tags = dict(re.findall(tag_regex, body, re.IGNORECASE))

            self.from_tag = tags.get('from-tag')
            self.to_tag = tags.get('to-tag')

            # Check early-only flag
            self.early_only = 'early-only' in [p.lower().strip() for p in parts]

            # Parse additional parameters
            self.params = {}
            for param in parts[1:]:
                if '=' in param:
                    key, value = param.split('=', 1)
                    self.params[key.strip().lower()] = value.strip()
                elif param.lower() != 'early-only':
                    self.params[param.strip().lower()] = None

        except (IndexError, ValueError) as e:
            raise ValueError(f"Invalid Replaces header format: {body}")

    def __str__(self):
        header_parts = [self.call_id]

        if self.from_tag:
            header_parts.append(f"from-tag={self.from_tag}")

        if self.to_tag:
            header_parts.append(f"to-tag={self.to_tag}")

        if self.early_only:
            header_parts.append("early-only")

        # Add additional parameters
        for key, value in self.params.items():
            if value is not None:
                header_parts.append(f"{key}={value}")
            else:
                header_parts.append(key)

        return ';'.join(header_parts)

    def getCopy(self):
        return SipReplaces(
            call_id=self.call_id,
            from_tag=self.from_tag,
            to_tag=self.to_tag,
            early_only=self.early_only,
            params=deepcopy(self.params)
        )

    def match(self, other):
        if not isinstance(other, SipReplaces):
            return False

        return (
            self.call_id == other.call_id and
            self.from_tag == other.from_tag and
            self.to_tag == other.to_tag
        )

import re
import discord

# Regex patterns for different mention types
mass_mention = re.compile(r'@(everyone|here)')
member_mention = re.compile(r'<@!?(\d+)>')
role_mention = re.compile(r'<@&(\d+)>')
channel_mention = re.compile(r'<#(\d+)>')

def clean_member_name(member, fallback_id=True):
    """
    Clean and format member name with fallback options.

    Args:
        member (discord.Member): Discord member object
        fallback_id (bool): Use ID if display name is unavailable

    Returns:
        str: Cleaned member name
    """
    if member is None:
        return "Unknown User"

    try:
        if member.display_name:
            return member.display_name
        elif fallback_id:
            return f"User({member.id})"
        else:
            return "Unknown User"
    except AttributeError:
        return "Deleted User"

def clean_role_name(role, fallback_id=True):
    """
    Clean and format role name with fallback options.

    Args:
        role (discord.Role): Discord role object
        fallback_id (bool): Use ID if role name is unavailable

    Returns:
        str: Cleaned role name
    """
    if role is None:
        return "Unknown Role"

    try:
        if role.name:
            return role.name
        elif fallback_id:
            return f"Role({role.id})"
        else:
            return "Unknown Role"
    except AttributeError:
        return "Deleted Role"

def clean_channel_name(channel, fallback_id=True):
    """
    Clean and format channel name with fallback options.

    Args:
        channel (discord.TextChannel): Discord channel object
        fallback_id (bool): Use ID if channel name is unavailable

    Returns:
        str: Cleaned channel name
    """
    if channel is None:
        return "Unknown Channel"

    try:
        if channel.name:
            return channel.name
        elif fallback_id:
            return f"Channel({channel.id})"
        else:
            return "Unknown Channel"
    except AttributeError:
        return "Deleted Channel"

def clean(message, guild=None, zero_width=True, max_mentions=None):
    """
    Clean Discord message content, removing or transforming mentions.

    Args:
        message (str): Original message content
        guild (discord.Guild): Guild context for resolving mentions
        zero_width (bool): Replace mentions with zero-width space
        max_mentions (int, optional): Limit number of mentions allowed

    Returns:
        str: Cleaned message content
    """
    if not message:
        return message

    # Count initial mentions
    member_mentions_count = len(member_mention.findall(message))
    role_mentions_count = len(role_mention.findall(message))
    channel_mentions_count = len(channel_mention.findall(message))
    mass_mentions_count = len(mass_mention.findall(message))

    total_mentions = member_mentions_count + role_mentions_count + channel_mentions_count + mass_mentions_count

    if max_mentions is not None and total_mentions > max_mentions:
        return "Too many mentions"

    # Replace mass mentions
    if guild:
        message = mass_mention.sub(r'\1', message)

    # Replace member mentions
    def replace_member_mention(match):
        member_id = int(match.group(1))
        if guild:
            member = guild.get_member(member_id)
            return clean_member_name(member) if zero_width else match.group(0)
        return '\u200b' if zero_width else match.group(0)

    message = member_mention.sub(replace_member_mention, message)

    # Replace role mentions
    def replace_role_mention(match):
        role_id = int(match.group(1))
        if guild:
            role = guild.get_role(role_id)
            return clean_role_name(role) if zero_width else match.group(0)
        return '\u200b' if zero_width else match.group(0)

    message = role_mention.sub(replace_role_mention, message)

    # Replace channel mentions
    def replace_channel_mention(match):
        channel_id = int(match.group(1))
        if guild:
            channel = guild.get_channel(channel_id)
            return clean_channel_name(channel) if zero_width else match.group(0)
        return '\u200b' if zero_width else match.group(0)

    message = channel_mention.sub(replace_channel_mention, message)

    return message

def is_clean(message):
    """
    Check if message contains any mentions.

    Args:
        message (str): Message content to check

    Returns:
        bool: True if message is clean (no mentions), False otherwise
    """
    mentions = (
        member_mention.search(message) or
        role_mention.search(message) or
        channel_mention.search(message) or
        mass_mention.search(message)
    )
    return mentions is None

def pretty_concat(items, separator=', ', last_separator=' and '):
    """
    Concatenate list of items with configurable separators.

    Args:
        items (list): List of items to concatenate
        separator (str): Separator between items
        last_separator (str): Separator for last item

    Returns:
        str: Concatenated string
    """
    if not items:
        return ''
    if len(items) == 1:
        return str(items[0])
    return separator.join(map(str, items[:-1])) + last_separator + str(items[-1])

import frappe
from frappe.model.document import Document
from frappe import _, throw

class Role(Document):
    def before_rename(self, old_name, new_name, merge=False):
        """
        Prevent renaming of standard system roles
        """
        if old_name in ['Administrator', 'Guest']:
            throw(_("Cannot rename standard roles"))

        if frappe.db.exists('Role', new_name):
            throw(_("Role already exists"))

    def validate(self):
        """
        Validate role configuration and prevent modifications to core roles
        """
        if self.is_standard and not frappe.session.user == 'Administrator':
            throw(_("Cannot modify standard roles"))

        # Prevent duplicate roles
        if not self.is_new() and frappe.db.exists('Role', {'role_name': self.role_name}):
            throw(_("Role with this name already exists"))

        self.set_desk_properties()

    def disable_role(self):
        """
        Disable a specific role and update related user permissions
        """
        if self.role_name in ['Administrator', 'Guest']:
            throw(_("Cannot disable system roles"))

        self.disabled = 1
        self.remove_roles()
        self.save()

    def set_desk_properties(self):
        """
        Configure desk access properties for the role
        """
        desk_properties = (
            'desk_access', 
            'view_all_records', 
            'create_records', 
            'edit_records', 
            'delete_records'
        )

        for prop in desk_properties:
            if hasattr(self, prop):
                frappe.db.set_value('Role', self.name, prop, getattr(self, prop))

    def remove_roles(self):
        """
        Remove role assignments when role is disabled
        """
        frappe.db.delete('Has Role', {'role': self.name})

    @staticmethod
    def get_info_based_on_role(role):
        """
        Retrieve comprehensive information about a specific role
        """
        role_info = frappe.get_doc('Role', role)
        return {
            'name': role_info.name,
            'role_name': role_info.role_name,
            'disabled': role_info.disabled,
            'desk_access': getattr(role_info, 'desk_access', False),
            'users': Role.get_users(role)
        }

    @staticmethod
    def get_user_info(role):
        """
        Get user details associated with a specific role
        """
        users = Role.get_users(role)
        return [frappe.get_doc('User', user) for user in users]

    @staticmethod
    def get_users(role):
        """
        Retrieve list of users assigned to a specific role
        """
        return [hr.parent for hr in frappe.get_all('Has Role', 
                                                   filters={'role': role}, 
                                                   fields=['parent'])]

    @frappe.whitelist()
    def role_query(self, query_type='all', filters=None):
        """
        Advanced role querying mechanism
        """
        if not filters:
            filters = {}

        query_methods = {
            'all': self.get_all_roles,
            'active': self.get_active_roles,
            'disabled': self.get_disabled_roles
        }

        return query_methods.get(query_type, self.get_all_roles)(filters)

    def get_all_roles(self, filters):
        """
        Retrieve all roles with optional filtering
        """
        return frappe.get_list('Role', filters=filters)

    def get_active_roles(self, filters):
        """
        Get active (non-disabled) roles
        """
        filters['disabled'] = 0
        return frappe.get_list('Role', filters=filters)

    def get_disabled_roles(self, filters):
        """
        Get disabled roles
        """
        filters['disabled'] = 1
        return frappe.get_list('Role', filters=filters)

