import sys
import getopt
import happy.Utils as Utils
from WeavePing import WeavePing

def print_usage():
    print("Usage: weave-ping.py [options]")
    print("    -h, --help                 Print this help menu")
    print("    -c, --count <num>          Number of ping requests")
    print("    -i, --interval <ms>        Interval between ping requests")
    print("    -t, --timeout <ms>         Timeout for ping response")
    print("    -p, --protocol <protocol>  Network protocol (TCP/UDP/WRMP)")
    print("    -C, --case                 Enable CASE authentication")
    print("    -q, --quiet                Suppress verbose output")
    print("    -a, --client <node>        Source/client node")
    print("    -b, --server <node>        Destination/server node")

def parse_arguments(argv):
    options = {
        'count': 5,
        'interval': 1000,
        'timeout': 5000,
        'protocol': 'WRMP',
        'case': False,
        'quiet': False,
        'client': None,
        'server': None
    }

    try:
        opts, args = getopt.getopt(argv, 
            "hc:i:t:p:Cqa:b:", 
            ["help", "count=", "interval=", "timeout=", 
             "protocol=", "case", "quiet", "client=", "server="])
    except getopt.GetoptError as err:
        print(str(err))
        print_usage()
        sys.exit(2)

    for opt, arg in opts:
        if opt in ("-h", "--help"):
            print_usage()
            sys.exit()
        elif opt in ("-c", "--count"):
            options['count'] = int(arg)
        elif opt in ("-i", "--interval"):
            options['interval'] = int(arg)
        elif opt in ("-t", "--timeout"):
            options['timeout'] = int(arg)
        elif opt in ("-p", "--protocol"):
            options['protocol'] = arg.upper()
        elif opt in ("-C", "--case"):
            options['case'] = True
        elif opt in ("-q", "--quiet"):
            options['quiet'] = True
        elif opt in ("-a", "--client"):
            options['client'] = arg
        elif opt in ("-b", "--server"):
            options['server'] = arg

    return options

def validate_configuration(options):
    if not options['client']:
        print("Error: Client node must be specified")
        sys.exit(2)
    if not options['server']:
        print("Error: Server node must be specified")
        sys.exit(2)

    valid_protocols = ['TCP', 'UDP', 'WRMP']
    if options['protocol'] not in valid_protocols:
        print(f"Error: Invalid protocol. Must be one of {valid_protocols}")
        sys.exit(2)

def configure_network_test(options):
    weave_ping = WeavePing()

    weave_ping.option('count', options['count'])
    weave_ping.option('interval', options['interval'])
    weave_ping.option('timeout', options['timeout'])
    weave_ping.option('protocol', options['protocol'])

    if options['case']:
        weave_ping.option('security', 'case')

    return weave_ping

def execute_network_test(weave_ping, options):
    try:
        result = weave_ping.WeavePing(
            client_node=options['client'],
            server_node=options['server']
        )

        if not options['quiet']:
            print(f"Ping Test Results: {result}")

        return result
    except Exception as e:
        print(f"Network ping test failed: {e}")
        sys.exit(1)

def main(argv):
    try:
        options = parse_arguments(argv)
        validate_configuration(options)

        weave_ping = configure_network_test(options)
        execute_network_test(weave_ping, options)

    except KeyboardInterrupt:
        print("\nPing test interrupted by user")
        sys.exit(1)

if __name__ == "__main__":
    main(sys.argv[1:])

import os
import subprocess
from typing import List, Dict, Optional, Callable
from sqlalchemy import create_engine, MetaData, Table, Column, String, DateTime
from sqlalchemy.orm import sessionmaker
from sqlalchemy.sql import text
from sqlalchemy.exc import SQLAlchemyError

class FileLoader:
    def __init__(self, binary: str = 'psql', args: List[str] = None):
        self.binary = binary
        self.args = args or []

    def __call__(self, filepath: str, connection_string: str) -> bool:
        try:
            cmd = [self.binary] + self.args + ['-f', filepath, connection_string]
            result = subprocess.run(cmd, capture_output=True, text=True)
            return result.returncode == 0
        except Exception as e:
            print(f"Migration file execution error: {e}")
            return False

class PygrationState:
    def __init__(
        self, 
        connection_string: str, 
        schema: str = 'public',
        table_name: str = 'pygration_state'
    ):
        self.connection_string = connection_string
        self.schema = schema
        self.table_name = table_name
        self.engine = create_engine(connection_string)
        self.metadata = MetaData(schema=schema)

        self.pygration_state = Table(
            table_name,
            self.metadata,
            Column('migration_id', String, primary_key=True),
            Column('applied_at', DateTime, nullable=False),
            schema=schema
        )

        self.Session = sessionmaker(bind=self.engine)

    def create_state_table(self):
        try:
            self.metadata.create_all(self.engine)
        except SQLAlchemyError as e:
            print(f"Error creating state table: {e}")

    def record_migration(self, migration_id: str):
        try:
            with self.Session() as session:
                session.execute(
                    text('INSERT INTO {}.{} (migration_id, applied_at) VALUES (:id, NOW())'.format(
                        self.schema, self.table_name
                    )), 
                    {'id': migration_id}
                )
                session.commit()
        except SQLAlchemyError as e:
            print(f"Migration recording error: {e}")

    def check_migration_status(self, migration_id: str) -> bool:
        try:
            with self.Session() as session:
                result = session.execute(
                    text('SELECT COUNT(*) FROM {}.{} WHERE migration_id = :id'.format(
                        self.schema, self.table_name
                    )), 
                    {'id': migration_id}
                )
                return result.scalar() > 0
        except SQLAlchemyError as e:
            print(f"Migration status check error: {e}")
            return False

class MigrationManager:
    def __init__(
        self, 
        connection_string: str, 
        migrations_dir: str, 
        file_loader: Optional[FileLoader] = None
    ):
        self.connection_string = connection_string
        self.migrations_dir = migrations_dir
        self.file_loader = file_loader or FileLoader()
        self.state_tracker = PygrationState(connection_string)
        self.state_tracker.create_state_table()

    def get_migration_files(self) -> List[str]:
        files = sorted([
            f for f in os.listdir(self.migrations_dir) 
            if f.endswith('.sql') and not self.state_tracker.check_migration_status(f)
        ])
        return [os.path.join(self.migrations_dir, file) for file in files]

    def apply_migrations(
        self, 
        filter_func: Optional[Callable[[str], bool]] = None
    ):
        migration_files = self.get_migration_files()

        if filter_func:
            migration_files = list(filter(filter_func, migration_files))

        for migration_file in migration_files:
            migration_id = os.path.basename(migration_file)

            if self.file_loader(migration_file, self.connection_string):
                self.state_tracker.record_migration(migration_id)
                print(f"Successfully applied migration: {migration_id}")
            else:
                print(f"Migration failed: {migration_id}")
                break

def main():
    connection_string = "postgresql://username:password@localhost/database"
    migrations_path = "./migrations"

    migration_manager = MigrationManager(
        connection_string, 
        migrations_path
    )
    migration_manager.apply_migrations()

if __name__ == "__main__":
    main()

import os
import shutil
import subprocess
from typing import Optional, List, Callable, Dict, Union

class IdeaNotFoundException(Exception):
    """Raised when IDEA executable cannot be found."""
    pass

class OpenError(Exception):
    """Raised when file opening fails."""
    pass

def _cmd_exists(cmd: str) -> bool:
    """Check if command exists in system path."""
    return shutil.which(cmd) is not None

def _mac_open_with_idea(paths: List[str], idea_path: Optional[str] = None) -> None:
    """Open files in macOS IntelliJ IDEA."""
    if not idea_path:
        idea_paths = [
            "/Applications/IntelliJ IDEA.app/Contents/MacOS/idea",
            "/Applications/IntelliJ IDEA CE.app/Contents/MacOS/idea"
        ]
        idea_path = next((p for p in idea_paths if os.path.exists(p)), None)

    if not idea_path:
        raise IdeaNotFoundException("IntelliJ IDEA executable not found")

    try:
        subprocess.run([idea_path, *paths], check=True)
    except subprocess.CalledProcessError as e:
        raise OpenError(f"Failed to open files in IDEA: {e}")

def _mac_open(paths: List[str]) -> None:
    """Open files in default macOS viewer."""
    try:
        subprocess.run(["open", *paths], check=True)
    except subprocess.CalledProcessError as e:
        raise OpenError(f"Failed to open files: {e}")

def _linux_open_with_idea(paths: List[str]) -> None:
    """Open files in Linux IntelliJ IDEA."""
    idea_cmds = ["idea", "intellij-idea", "intellij-idea-community"]
    idea_cmd = next((cmd for cmd in idea_cmds if _cmd_exists(cmd)), None)

    if not idea_cmd:
        raise IdeaNotFoundException("IntelliJ IDEA executable not found")

    try:
        subprocess.run([idea_cmd, *paths], check=True)
    except subprocess.CalledProcessError as e:
        raise OpenError(f"Failed to open files in IDEA: {e}")

def _linux_open(paths: List[str]) -> None:
    """Open files in default Linux viewer."""
    try:
        subprocess.run(["xdg-open", *paths], check=True)
    except subprocess.CalledProcessError as e:
        raise OpenError(f"Failed to open files: {e}")

def _windows_open_with_idea(paths: List[str]) -> None:
    """Open files in Windows IntelliJ IDEA."""
    # Placeholder for Windows implementation
    raise NotImplementedError("Windows IDEA opening not yet supported")

def _windows_open(paths: List[str]) -> None:
    """Open files in default Windows viewer."""
    # Placeholder for Windows implementation
    raise NotImplementedError("Windows file opening not yet supported")

_OPENER_BY_OS: Dict[str, Callable[[List[str]], None]] = {
    'Darwin': _mac_open,
    'Linux': _linux_open,
    'Windows': _windows_open
}

_IDEA_BY_OS: Dict[str, Callable[[List[str], Optional[str]], None]] = {
    'Darwin': _mac_open_with_idea,
    'Linux': _linux_open_with_idea,
    'Windows': _windows_open_with_idea
}

def idea_open(paths: Union[str, List[str]], idea_path: Optional[str] = None) -> None:
    """
    Open files in IntelliJ IDEA across platforms.

    Args:
        paths: Single path or list of file paths to open
        idea_path: Optional custom path to IDEA executable
    """
    platform = os.uname().sysname

    if not isinstance(paths, list):
        paths = [paths]

    try:
        _IDEA_BY_OS.get(platform, lambda p, ip: None)(paths, idea_path)
    except IdeaNotFoundException:
        raise

def ui_open(paths: Union[str, List[str]]) -> None:
    """
    Open files in default system viewer across platforms.

    Args:
        paths: Single path or list of file paths to open
    """
    platform = os.uname().sysname

    if not isinstance(paths, list):
        paths = [paths]

    try:
        _OPENER_BY_OS.get(platform, lambda p: None)(paths)
    except OpenError:
        raise

import math
import sqlite3
from typing import List, Dict, Optional, Any

class DatabaseConnectionManager:
    def __init__(self, connection_string: str):
        self.connection_string = connection_string
        self._connection = None

    def __enter__(self):
        self._connection = sqlite3.connect(self.connection_string)
        return self._connection

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self._connection:
            self._connection.close()

class InverseDocumentFrequencyVector:
    def __init__(self, vector_values: Dict[str, float]):
        self.vector_values = vector_values

    def get_value(self, term: str) -> Optional[float]:
        return self.vector_values.get(term)

    def __repr__(self):
        return f"InverseDocumentFrequencyVector(terms={len(self.vector_values)})"

class InverseDocumentFrequencyVectorCreator:
    def __init__(self, db_connection_str: str):
        self.db_connection_str = db_connection_str

    @staticmethod
    def log_10(value: float) -> float:
        return math.log10(max(value, 1))

    def _create_log_function(self, connection: sqlite3.Connection):
        connection.create_function('LOG10', 1, self.log_10)

    def _create_inverse_document_frequency_view(self, connection: sqlite3.Connection, total_documents: int):
        connection.execute('''
            CREATE TEMPORARY VIEW document_frequency_view AS
            SELECT term, 
                   COUNT(DISTINCT document_id) as document_frequency,
                   LOG10(? * 1.0 / COUNT(DISTINCT document_id)) as idf_value
            FROM document_terms
            GROUP BY term
        ''', (total_documents,))

    def _get_vector_values_from_db(self, connection: sqlite3.Connection) -> Dict[str, float]:
        cursor = connection.cursor()
        cursor.execute('SELECT term, idf_value FROM document_frequency_view')
        return dict(cursor.fetchall())

    def _create_vector(self, filter_conditions: Optional[str] = None) -> InverseDocumentFrequencyVector:
        with DatabaseConnectionManager(self.db_connection_str) as connection:
            self._create_log_function(connection)

            total_documents_query = 'SELECT COUNT(DISTINCT document_id) FROM documents'
            if filter_conditions:
                total_documents_query += f' WHERE {filter_conditions}'

            cursor = connection.cursor()
            cursor.execute(total_documents_query)
            total_documents = cursor.fetchone()[0]

            self._create_inverse_document_frequency_view(connection, total_documents)
            vector_values = self._get_vector_values_from_db(connection)

        return InverseDocumentFrequencyVector(vector_values)

    def create_idf_vector(self, filter_conditions: Optional[str] = None) -> InverseDocumentFrequencyVector:
        return self._create_vector(filter_conditions)

class TextVectorProcessor:
    def __init__(self, vector_creator: InverseDocumentFrequencyVectorCreator):
        self.vector_creator = vector_creator

    def process_document_collection(self, document_types: List[str]):
        filter_conditions = f"document_type IN ({','.join(['?']*len(document_types))})"
        return self.vector_creator.create_idf_vector(filter_conditions)

    def compute_weighted_representation(self, document_vector: InverseDocumentFrequencyVector, terms: List[str]) -> float:
        return sum(
            document_vector.get_value(term) or 0 for term in terms
        )

