import pytest
from ansible.modules.network.cloudengine import ce_is_is_instance
from units.modules.network.cloudengine.test_ce_is_is_instance import TestCloudEngineIsIsInstanceModule
from units.compat.mock import patch, MagicMock

class TestCloudEngineIsIsInstanceModule:
    def setUp(self):
        """
        Setup method for initializing test environment
        """
        self.mock_module = MagicMock()
        self.mock_netconf = MagicMock()

    def tearDown(self):
        """
        Cleanup method after test execution
        """
        pass

    def load_fixture(self, filename):
        """
        Load mock configuration fixture for testing
        """
        fixture_path = f'fixtures/{filename}'
        with open(fixture_path, 'r') as fixture_file:
            return fixture_file.read()

    def set_module_args(self, args):
        """
        Set module arguments for testing
        """
        self.mock_module.params.update(args)

    def execute_module(self, failed=False):
        """
        Execute module with predefined configuration
        """
        with patch.object(ce_is_is_instance, 'connect') as mock_connect:
            mock_connect.return_value = self.mock_netconf
            result = ce_is_is_instance.main()

            if failed:
                assert result['failed'] is True
            else:
                assert result['changed'] is True

    @pytest.mark.parametrize('instance_config', [
        {
            'instance_id': '1',
            'vpn_name': 'default',
            'state': 'present'
        },
        {
            'instance_id': '2',
            'vpn_name': 'management',
            'state': 'present'
        }
    ])
    def test_isis_instance_present(self, instance_config):
        """
        Test IS-IS instance creation scenarios
        """
        self.set_module_args({
            'instance_id': instance_config['instance_id'],
            'vpn_name': instance_config['vpn_name'],
            'state': instance_config['state']
        })

        fixture_data = self.load_fixture('isis_instance_present.xml')
        self.mock_netconf.get_config.return_value = fixture_data

        self.execute_module()

    @pytest.mark.parametrize('instance_config', [
        {
            'instance_id': '1',
            'vpn_name': 'default',
            'state': 'absent'
        },
        {
            'instance_id': '2',
            'vpn_name': 'management',
            'state': 'absent'
        }
    ])
    def test_isis_instance_absent(self, instance_config):
        """
        Test IS-IS instance removal scenarios
        """
        self.set_module_args({
            'instance_id': instance_config['instance_id'],
            'vpn_name': instance_config['vpn_name'],
            'state': instance_config['state']
        })

        fixture_data = self.load_fixture('isis_instance_absent.xml')
        self.mock_netconf.get_config.return_value = fixture_data

        self.execute_module()

    def test_invalid_instance_configuration(self):
        """
        Test handling of invalid IS-IS instance configurations
        """
        self.set_module_args({
            'instance_id': '999',
            'vpn_name': 'invalid_vpn',
            'state': 'present'
        })

        self.execute_module(failed=True)

import pytest
import socket
import logging
import json
from unittest.mock import patch
from pygelf import graylog_handler
from pygelf.constants import SYSLOG_LEVEL_ERROR, SYSLOG_LEVEL_WARNING

def get_unique_message():
    return f"Test Message: {socket.gethostname()}"

@pytest.fixture(params=[
    'tcp', 'udp', 'http', 'https', 'tls'
])
def gelf_handler(request):
    host = 'localhost'
    port = 12201

    if request.param == 'tcp':
        return graylog_handler.GelfTcpHandler(
            host=host,
            port=port,
            debug=True
        )
    elif request.param == 'udp':
        return graylog_handler.GelfUdpHandler(
            host=host,
            port=port,
            debug=True
        )
    elif request.param == 'http':
        return graylog_handler.GelfHttpHandler(
            host=host,
            port=port,
            debug=True
        )
    elif request.param == 'https':
        return graylog_handler.GelfHttpsHandler(
            host=host,
            port=port,
            debug=True,
            validate_cert=False
        )
    elif request.param == 'tls':
        return graylog_handler.GelfTlsHandler(
            host=host,
            port=port,
            debug=True
        )

def test_simple_message(gelf_handler):
    logger = logging.getLogger('test_logger')
    logger.addHandler(gelf_handler)

    message = get_unique_message()
    logger.info(message)

    assert gelf_handler.last_message is not None
    assert json.loads(gelf_handler.last_message)['short_message'] == message

def test_formatted_message(gelf_handler):
    logger = logging.getLogger('test_logger')
    logger.addHandler(gelf_handler)

    message_template = "User: {username}, Action: {action}"
    context = {
        'username': 'john_doe',
        'action': 'login'
    }

    logger.info(message_template.format(**context))

    log_record = json.loads(gelf_handler.last_message)
    assert 'username' in log_record['additional']
    assert 'action' in log_record['additional']

def test_log_warning(gelf_handler):
    logger = logging.getLogger('test_logger')
    logger.addHandler(gelf_handler)

    warning_message = get_unique_message()
    logger.warning(warning_message)

    log_record = json.loads(gelf_handler.last_message)
    assert log_record['level'] == SYSLOG_LEVEL_WARNING

def test_log_exception(gelf_handler):
    logger = logging.getLogger('test_logger')
    logger.addHandler(gelf_handler)

    try:
        raise ValueError("Test Exception")
    except ValueError:
        logger.exception("Exception occurred")

    log_record = json.loads(gelf_handler.last_message)
    assert log_record['level'] == SYSLOG_LEVEL_ERROR
    assert 'traceback' in log_record['additional']

def test_source_identification(gelf_handler):
    logger = logging.getLogger('test_logger')
    logger.addHandler(gelf_handler)

    with patch('socket.gethostname', return_value='test_host'):
        message = get_unique_message()
        logger.info(message)

        log_record = json.loads(gelf_handler.last_message)
        assert log_record['host'] == 'test_host'
